using GManager.Client.Protocol;using GManager.Client.Service;
var enroll=args.Contains("--enroll-stdin",StringComparer.OrdinalIgnoreCase);var builder=Host.CreateApplicationBuilder(args);builder.Services.AddWindowsService(options=>options.ServiceName="G-Manager Gaming Client");builder.Services.AddSingleton<ProtectedIdentityStore>();builder.Services.AddSingleton<StationPolicyEnforcer>();builder.Services.AddSingleton<ClientRuntime>();builder.Services.AddHttpClient<IMachineProtocolClient,MachineProtocolClient>((services,http)=>http.BaseAddress=new Uri(services.GetRequiredService<IConfiguration>()["Backend:BaseUrl"]??"https://localhost:8080/"));if(!enroll)builder.Services.AddHostedService<ClientWorker>();var host=builder.Build();
if(enroll){var token=Console.ReadLine()??throw new InvalidOperationException("Enrollment token is required on stdin.");using var signer=new Ed25519Signer();var protocol=host.Services.GetRequiredService<IMachineProtocolClient>();var result=await protocol.EnrollAsync(token,signer,"0.1.0-dev",CancellationToken.None);host.Services.GetRequiredService<ProtectedIdentityStore>().Save(new(result.IdentityId,result.StationId,result.KeyVersion,signer.Export()));return;}await host.RunAsync();
